#!/usr/bin/env python3
"""Embed the local dashboard HTML into an ESP32 PROGMEM header."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
html_path = ROOT / "dashboard" / "index.html"
header_path = ROOT / "code" / "esp32" / "local_dashboard" / "dashboard_html.h"

html = html_path.read_text(encoding="utf-8")
if ")dashboard\"" in html:
    raise SystemExit("HTML contains the raw-string delimiter; choose another delimiter.")

header_path.parent.mkdir(parents=True, exist_ok=True)
header = (
    "// Generated by tools/embed_dashboard.py from dashboard/index.html.\n"
    "// Do not edit this file by hand; edit the HTML source and rerun the script.\n"
    "#pragma once\n"
    "#include <Arduino.h>\n\n"
    'const char DASHBOARD_HTML[] PROGMEM = R"dashboard(' + html + ')dashboard";\n'
)
header_path.write_text(header, encoding="utf-8")
print(f"Wrote {header_path} ({len(html)} HTML bytes)")
